{
  "risks": [
    {
      "condition": "The service must be live for students by 2027-01-11, but the migration of signed records is only scheduled by 2027-02-28, and work package 3.1 depends on work packages 1.2 and 2.1.",
      "event": "Go-live occurs on 2027-01-11 before historical signed records are fully migrated from the current tool.",
      "effect": "Students and staff cannot access prior signed documents during spring enrollment, leading to operational friction and complaints.",
      "assumptions": [
        "Historical records are not strictly required on day one of spring enrollment."
      ],
      "owner_role": "Delivery lead",
      "trigger": "Migration finish date remains set to 2027-02-28 while go-live is confirmed for 2027-01-11.",
      "responses": [
        "Accelerate migration to complete before 2027-01-11.",
        "Agree with the College to provide access to the legacy archive for historical lookups until migration finishes."
      ],
      "residual_exposure": "Historical records are temporarily unavailable in the new system after go-live.",
      "evidence_src_ids": [
        "SRC-0026",
        "SRC-0032"
      ],
      "affects": [
        "1.2",
        "3.1",
        "REQ-0007",
        "REQ-0012"
      ]
    },
    {
      "condition": "Proposals must be submitted as a single PDF of no more than 20 pages by 2026-12-01 12:00 UTC.",
      "event": "The final bid document exceeds 20 pages or is uploaded past the deadline due to portal congestion.",
      "effect": "The proposal is rejected outright without evaluation.",
      "assumptions": [
        "The procurement portal will remain accessible and stable right up to the deadline."
      ],
      "owner_role": "Bid manager",
      "trigger": "Draft proposal length reaches 18 pages prior to final review.",
      "responses": [
        "Enforce a strict 18-page limit during drafting.",
        "Upload the proposal 24 hours prior to the deadline."
      ],
      "residual_exposure": "Potential portal outage on the final day, mitigated by early submission.",
      "evidence_src_ids": [
        "SRC-0015"
      ],
      "affects": [
        "REQ-0001"
      ]
    }
  ],
  "open_questions": [
    {
      "text": "Does the migration deadline of 2027-02-28 take precedence over the spring enrollment go-live date of 2027-01-11 for historical records accessibility?",
      "src_ids": [
        "SRC-0026",
        "SRC-0032"
      ]
    }
  ]
}

